continue_hover:

cRSubGame* live_game = game;
cRSubGoldy* live_player = player;
int* completion_row = &live_game->completion_row_start;
if (next_progress > 1.0f
    || (float)(*completion_row - 5) < live_player->transform.position.z) {
    goto finish_hover;
}

cRSubGame* live_game = game;
cRSubGoldy* live_player = player;
float* player_z = &live_player->transform.position.z;
if (next_progress > 1.0f
    || (float)(live_game->completion_row_start - 5) < *player_z) {
    goto finish_hover;
}

cRSubGame* live_game = game;
cRSubGoldy* live_player = player;
TransformMatrix* live_transform = &live_player->transform;
if (next_progress > 1.0f
    || (float)(live_game->completion_row_start - 5) < live_transform->position.z) {
    goto finish_hover;
}

cRSubGame* const live_game = game;
